export interface DraggableAttrs {
    sinceMouseDown: {
        x: number;
        y: number;
    };
}
export interface Props {
    /**
     * Drag distance in pixel that needed to trigger the increment/decrement event.
     *
     * Default is 1, which mean the `onSpin` callback will be
     * invoked on every 1px drag distance made.
     */
    dragScale?: number;
    /**
     * Spinner bar animation speed multiplier.
     */
    animationSpeed?: number;
    /**
     * Callback that will be invoked on increment/decrement event start.
     */
    onSpinStart?: () => void;
    /**
     * Callback that will be invoked on increment/decrement event.
     *
     * Param `+` is increment event.
     * Param `-` is decrement event.
     */
    onSpin?: (operation: '+' | '-') => void;
    /**
     * Callback that will be invoked on increment/decrement event end.
     */
    onSpinEnd?: () => void;
}
